   339→        // Module 5: SequenceGenerator
   340→        test('SequenceGenerator produces correct frame count', function() {
   341→          const program = [
   342→            InstructionSet.createInstruction('ADDI', { rs: 0, rt: 8, immediate: 10 }),
   343→            InstructionSet.createInstruction('ADDI', { rs: 0, rt: 9, immediate: 20 })
